package com.greenlink.controller;import com.greenlink.dto.RequestView;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.RequestService;import java.util.*;import org.bson.types.ObjectId;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/requests") public class RequestController {private final RequestService s;public RequestController(RequestService s){this.s=s;} @PostMapping public ResponseEntity<RequestView> create(@AuthenticationPrincipal AppUserPrincipal p,@RequestBody Map<String,Object> b){int qty=1;if(b.containsKey("quantity")&&b.get("quantity")!=null){try{qty=Integer.parseInt(b.get("quantity").toString());}catch(Exception ignored){}}return ResponseEntity.status(201).body(s.create(new ObjectId(p.getId()),(String)b.get("listingId"),(String)b.getOrDefault("message",""),qty));} @GetMapping("/mine") public List<RequestView> mine(@AuthenticationPrincipal AppUserPrincipal p){return s.mine(new ObjectId(p.getId()));} @GetMapping("/incoming") public List<RequestView> incoming(@AuthenticationPrincipal AppUserPrincipal p){return s.incoming(new ObjectId(p.getId()));} @PutMapping("/{id}/status") public RequestView status(@AuthenticationPrincipal AppUserPrincipal p,@PathVariable String id,@RequestBody Map<String,String> b){return s.status(new ObjectId(p.getId()),new ObjectId(id),b.get("status"));}}
